package factories

import (
	"context"
	"database/sql"
	"encoding/json"
	"fmt"
	"github.com/go-faker/faker/v4"
	"mbvlabs/internal/storage"
	"mbvlabs/models"
	"time"
)

// Factory declarations below are generated by Andurel.

type BlogPostFactory struct {
	models.BlogPostEntity
}

type BlogPostOption func(*BlogPostFactory)

func BuildBlogPost(opts ...BlogPostOption) models.BlogPostEntity {
	f := &BlogPostFactory{
		BlogPostEntity: models.BlogPostEntity{
			Title:               faker.Word(),
			Slug:                faker.Word(),
			Excerpt:             sql.NullString{String: faker.Word(), Valid: true},
			Body:                faker.Word(),
			Status:              faker.Word(),
			CoverImageUrl:       sql.NullString{String: faker.Word(), Valid: true},
			Tags:                json.RawMessage{},
			PublishedAt:         sql.NullTime{Time: time.Now(), Valid: true},
			PublicationSchedule: json.RawMessage{},
		},
	}

	for _, opt := range opts {
		opt(f)
	}

	return f.BlogPostEntity
}

func CreateBlogPost(ctx context.Context, exec storage.Executor, opts ...BlogPostOption) (models.BlogPostEntity, error) {
	built := BuildBlogPost(opts...)

	entity := models.BlogPostEntity{
		ID:                  built.ID,
		CreatedAt:           time.Now(),
		UpdatedAt:           time.Now(),
		Title:               built.Title,
		Slug:                built.Slug,
		Excerpt:             built.Excerpt,
		Body:                built.Body,
		Status:              built.Status,
		CoverImageUrl:       built.CoverImageUrl,
		Tags:                built.Tags,
		PublishedAt:         built.PublishedAt,
		PublicationSchedule: built.PublicationSchedule,
	}

	if err := exec.NewInsert().Model(&entity).Returning("*").Scan(ctx); err != nil {
		return models.BlogPostEntity{}, err
	}

	return entity, nil
}

func CreateBlogPosts(ctx context.Context, exec storage.Executor, count int, opts ...BlogPostOption) ([]models.BlogPostEntity, error) {
	blogposts := make([]models.BlogPostEntity, 0, count)

	for i := 0; i < count; i++ {
		entity, err := CreateBlogPost(ctx, exec, opts...)
		if err != nil {
			return nil, fmt.Errorf("failed to create blogpost %d: %w", i+1, err)
		}
		blogposts = append(blogposts, entity)
	}

	return blogposts, nil
}

